#!/usr/bin/env node
/* keel-icons-mcp — a zero-dependency MCP server for keel's icon set.
 *
 * Exposes keel's icons over the Model Context Protocol (stdio transport,
 * newline-delimited JSON-RPC 2.0) so an AI agent can search, read, and
 * add an icon on its own: it calls get_icon, gets the one-line CSS rule,
 * and pastes it into a stylesheet that links keel.css.
 *
 * Data source: icons.json (generated by build.mjs). No dependencies —
 * runs on plain Node ≥18.
 *
 * Add to an MCP client (e.g. Claude Desktop) config:
 *   "keel-icons": { "command": "node",
 *                   "args": ["/abs/path/to/keel-icons-mcp.mjs"] }
 */
import { readFileSync } from "node:fs";
import { createInterface } from "node:readline";

const DB = JSON.parse(readFileSync(new URL("../data/icons.json", import.meta.url), "utf8"));
const ICONS = DB.icons;
const byName = new Map(ICONS.map((i) => [i.name, i]));

const ADD_HINT =
  "To use it: link keel.css (it has the .k-icon base), then add this one CSS rule " +
  "to any stylesheet, and place `<span class=\"k-icon k-icon--NAME\" aria-hidden=\"true\"></span>` " +
  "in your markup. The icon inherits font-size and color (currentColor).";

const TOOLS = [
  {
    name: "search_icons",
    description:
      "Search keel's icon set by name or tag/concept (e.g. 'money', 'ai', 'social', 'chart'). " +
      "Returns matching icons with their category and tags.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "search text matched against names and tags" },
        limit: { type: "number", description: "max results (default 25)" },
      },
      required: ["query"],
    },
  },
  {
    name: "get_icon",
    description:
      "Get one icon by exact name — returns the ready-to-paste CSS rule, the raw currentColor " +
      "SVG, the category, and instructions for adding it to a project.",
    inputSchema: {
      type: "object",
      properties: { name: { type: "string", description: "exact icon name, e.g. 'shield'" } },
      required: ["name"],
    },
  },
  {
    name: "list_categories",
    description: "List the icon categories with their labels and counts.",
    inputSchema: { type: "object", properties: {} },
  },
  {
    name: "list_icons",
    description: "List icon names, optionally filtered to one category id.",
    inputSchema: {
      type: "object",
      properties: { category: { type: "string", description: "category id, e.g. 'social' (omit for all)" } },
    },
  },
];

function callTool(name, args) {
  args = args || {};
  if (name === "search_icons") {
    const q = String(args.query || "").toLowerCase();
    const limit = Number(args.limit) || 25;
    const hits = ICONS.filter(
      (i) => i.name.includes(q) || (i.tags || []).some((t) => t.includes(q))
    ).slice(0, limit).map((i) => ({ name: i.name, category: i.category, tags: i.tags }));
    return { matches: hits.length, icons: hits };
  }
  if (name === "get_icon") {
    const i = byName.get(String(args.name || ""));
    if (!i) {
      const near = ICONS.filter((x) => x.name.includes(String(args.name || "")))
        .slice(0, 8).map((x) => x.name);
      return { error: `No icon named "${args.name}".`, didYouMean: near };
    }
    return { name: i.name, category: i.categoryLabel, tags: i.tags, css: i.css, svg: i.svg, howToAdd: ADD_HINT };
  }
  if (name === "list_categories") return { categories: DB.categories };
  if (name === "list_icons") {
    const cat = args.category ? String(args.category) : null;
    const names = ICONS.filter((i) => !cat || i.category === cat).map((i) => i.name);
    return { count: names.length, category: cat || "all", icons: names };
  }
  return { error: `Unknown tool "${name}".` };
}

/* ---- JSON-RPC over stdio ---- */
function send(msg) { process.stdout.write(JSON.stringify(msg) + "\n"); }
function reply(id, result) { send({ jsonrpc: "2.0", id, result }); }
function fail(id, code, message) { send({ jsonrpc: "2.0", id, error: { code, message } }); }

function handle(req) {
  const { id, method, params } = req;
  if (method === "initialize") {
    return reply(id, {
      protocolVersion: "2024-11-05",
      capabilities: { tools: {} },
      serverInfo: { name: "keel-icons", version: String(DB.count) + "-icons" },
    });
  }
  if (method === "tools/list") return reply(id, { tools: TOOLS });
  if (method === "tools/call") {
    const out = callTool(params?.name, params?.arguments);
    return reply(id, { content: [{ type: "text", text: JSON.stringify(out, null, 2) }] });
  }
  if (method === "ping") return reply(id, {});
  if (method && method.startsWith("notifications/")) return; // notifications: no reply
  if (id !== undefined) fail(id, -32601, `Method not found: ${method}`);
}

const rl = createInterface({ input: process.stdin });
rl.on("line", (line) => {
  line = line.trim();
  if (!line) return;
  let req;
  try { req = JSON.parse(line); } catch { return; }
  try { handle(req); } catch (e) {
    if (req && req.id !== undefined) fail(req.id, -32603, String(e && e.message || e));
  }
});
